import {parseAmount} from './amount-input.js';
export function googlePriceQuestion(input){const fields=[['Marca','make'],['Modelo','name'],['Año','year'],['Versión','version'],['Motor','engine'],['Transmisión','transmission'],['Tracción','drive'],['Carrocería','type'],['Combustible','fuel'],['Kilometraje','mileage'],['Condición','condition'],['Ciudad','city']];const description=fields.filter(([,k])=>input[k]).map(([label,k])=>label+': '+String(input[k]).slice(0,120)).join('; '),currency=input.currency==='BOB'?'BOB':'USD';return '¿Qué precio de venta rápida, precio justo y venta lenta recomendarías para este vehículo en el mercado boliviano? '+description+'. Usa precios actuales de Bolivia y considera exactamente esta versión y su estado. Responde con tres importes únicos, no rangos, en este formato: Venta rápida: '+currency+' importe; Precio justo: '+currency+' importe; Venta lenta: '+currency+' importe. Luego explica brevemente los motivos y cita fuentes. Distingue estimaciones de precios comprobados. No conviertas monedas con un tipo de cambio supuesto.';}
export const googlePriceUrl=input=>'https://www.google.com/search?hl=es&q='+encodeURIComponent(googlePriceQuestion(input));
export function parseGooglePrices(raw,currency='USD'){
 const text=String(raw||'').slice(0,60000).replace(/\u00a0/g,' ').replace(/\*\*/g,''),labels=[...text.matchAll(/(?:precio\s+de\s+)?venta\s+r[aá]pida|precio\s+justo|(?:precio\s+de\s+)?venta\s+lenta/gi)];
 const scenarios=[];for(let i=0;i<labels.length;i++){const label=labels[i],key=/r[aá]pida/i.test(label[0])?'quick':/justo/i.test(label[0])?'fair':'slow',segment=text.slice(label.index+label[0].length,labels[i+1]?.index??text.length).slice(0,160);const priceMatch=segment.match(/^\s*[:|–—-]?\s*(USD|US\$|\$us|U\$S|\$|BOB|Bs\.?)\s*([\d][\d., ]*)/i)||segment.match(/^\s*[:|–—-]?\s*([\d][\d., ]*)\s*(USD|US\$|\$us|U\$S|\$|BOB|Bs\.?)/i);if(!priceMatch)continue;const prefix=/^(USD|US\$|\$us|U\$S|\$|BOB|Bs\.?)$/i.test(priceMatch[1]),symbol=prefix?priceMatch[1]:priceMatch[2],price=parseAmount((prefix?priceMatch[2]:priceMatch[1]).trim());if((/BOB|Bs/i.test(symbol)?'BOB':'USD')!==currency||!Number.isFinite(price)||price<1000||price>5000000||/^\s*(?:[-–—]|a\s+\d|hasta\b)/i.test(segment.slice(priceMatch[0].length)))return[];if(scenarios.some(s=>s.key===key))return[];scenarios.push({key,label:{quick:'Venta rápida',fair:'Precio justo',slow:'Venta lenta'}[key],price,reason:'Importe de la respuesta de Google. Estimación orientativa para revisar antes de publicar.'});}
 const ordered=['quick','fair','slow'].map(k=>scenarios.find(s=>s.key===k));return ordered.every(Boolean)&&ordered[0].price<=ordered[1].price&&ordered[1].price<=ordered[2].price?ordered:[];
}
